'use strict';
const heritage=EldoriaHeritageModel;heritage.ensure(state);
for(const [id,puzzle]of Object.entries(heritage.puzzles))cityLife.P['heritage_'+id]=puzzle;
const heritageCSS=document.createElement('link');heritageCSS.rel='stylesheet';heritageCSS.href='city-heritage.css?v=1';document.head.append(heritageCSS);
const heritageButton=document.createElement('button');heritageButton.id='heritageBoard';heritageButton.textContent='Magic & the original shop';heritageButton.onclick=()=>heritageBoard();document.querySelector('.city-life-bar').append(heritageButton);
const heritageRooms={originalShop:{title:'The Original Shoemaker’s Shop',description:'The shoemaker and his wife’s furnished cottage from The Elves and the Shoemaker. Their bench, hearth, curtain, hand tools and thank-you clothes are preserved here.',district:'workshop'},memoryHall:{title:'Hall of Shared Memories',description:'A furnished gathering place for family stories, portrait conservation, remembrance lanterns and the community quilt.',district:'library'},spellAtelier:{title:'The Spell Atelier',description:'Learn silver-thread mending, Waylight constellations and the moonflower-growing charm. Practice before taking your magic into the city.',district:'academy'}};
const heritageDescriptionBefore=comfortPlaceDescription;comfortPlaceDescription=function(kind){return heritageRooms[kind]?.description||heritageDescriptionBefore(kind)};
const heritageWorkBefore=cityWorkLabel;cityWorkLabel=function(kind){return({originalShop:'Step into the original fairy tale',memoryHall:'Gather the kingdom’s memories',spellAtelier:'Learn a woodland spell'})[kind]||heritageWorkBefore(kind)};
const heritageUseBefore=cityUse;cityUse=function(kind){if(kind===cityInside&&heritageRooms[kind]){heritageRoom(kind);return}heritageUseBefore(kind)};
function heritageTravel(district,room,callback){lifeTravel({district,room},callback)}
function heritageOriginal(){heritageTravel('workshop','originalShop',()=>heritageRoom('originalShop'))}
function heritageRoom(kind){const r=heritageRooms[kind];if(!r||scene!==r.district||cityInside!==kind)return;modal(r.title,'<span class="city-eyebrow">'+(kind==='originalShop'?'THE ELVES AND THE SHOEMAKER · PRESERVED STORY SETTING':'A PLACE TO GATHER, LEARN AND BELONG')+'</span><p>'+lifeEsc(r.description)+'</p>'+(kind==='originalShop'?'<p class="life-dialogue">In gratitude to the shoemaker, his wife, and the two little helpers. The room remains a home: the tools are laid ready, the chairs wait beside the hearth, and the gifts remember an act of kindness.</p><p>The preserved shop belongs to the original tale. Your present-day craft orders are at the separate Silverstitch Workshop.</p>':''));lifePhoto(kind);if(kind==='originalShop'){action('Play the original fairy tale',()=>heritageActivity('originaltale'));action('Explore the preserved objects',heritageExhibits);action('Restore a treasured object',()=>heritageActivity('heirloom'));action('Make clothes for the helpers',()=>heritageActivity('gifts'));}if(kind==='memoryHall'){action('Begin a remembrance lantern',()=>heritageActivity('lantern'));action('Restore a family portrait',()=>heritageActivity('portraits'));action('Make the community quilt',()=>heritageActivity('quilt'));}if(kind==='spellAtelier'){for(const id of ['mending','waylight','bloom']){const a=heritage.activities.find(a=>a.id===id);action(a.title,()=>heritageActivity(id))}}action('All magical activities',()=>heritageBoard());action('Return to this room',()=>{$('modal').close();cityDraw()})}
function heritageExhibits(){if(!heritage.at({district:'workshop',room:'originalShop'},lifeWhere())){heritageTravel('workshop','originalShop',heritageExhibits);return}const h=heritage.ensure(state);modal('The room remembers','<p>Every object stays in its place. Examine the bench, gifts, tools, curtain and hearth to discover how the original story unfolded.</p><p>'+h.exhibits.length+' / '+heritage.exhibits.length+' objects remembered.</p>');heritage.exhibits.forEach(e=>action((h.exhibits.includes(e[0])?'✓ ':'')+e[1],()=>heritageExamine(e[0])));action('Return to the furnished shop',()=>{$('modal').close();cityDraw()})}
function heritageExamine(id){const r=heritage.examine(state,id,lifeWhere());if(!r.ok)return;lifeCommit();modal(r.exhibit[1],'<p class="life-dialogue">'+lifeEsc(r.exhibit[2])+'</p><p>'+state.cityHeritage.exhibits.length+' / 6 objects remembered.</p>');action('Examine another object',heritageExhibits);action('Play the original tale',()=>heritageActivity('originaltale'));action('Return to the shop',()=>{$('modal').close();cityDraw()})}
function heritageActivity(id){const i=heritage.current(state,id);if(!i)return;if(!heritage.at(i.step,lifeWhere())){heritageTravel(i.step.district,i.step.room,()=>heritageActivity(id));return}lifePuzzle('heritage_'+i.step.puzzle,i.activity.title+' · '+(i.index+1)+'/'+i.activity.steps.length+' · '+i.step.text,a=>{const r=heritage.answer(state,id,a,lifeWhere());if(r.ok&&!r.next){r.title+=r.practice?' · practice remembered':r.spell?' · a new spell learned':' · '+i.activity.prize;}return r},()=>{const next=heritage.current(state,id);modal('The next thread','<p>Your progress is saved.</p><h3>'+lifeEsc(next.step.text)+'</h3><p>'+lifeEsc(cityRoomNames[next.step.room]||next.step.room)+' · '+lifeEsc(cityShort[next.step.district])+'</p>');action('Continue this activity',()=>heritageActivity(id));action('Pause and explore',()=>{$('modal').close();cityDraw()})})}
function heritageBoard(tab='activities'){const h=heritage.ensure(state);modal('Magic, memories & the original shop','<p>The original shoemaker’s cottage is preserved in the Shoemaker’s Quarter. The city also has a Hall of Shared Memories and a Spell Atelier, each with activities of its own.</p><div id="heritageTabs" class="life-tabs"></div><div id="heritageContent"></div>');for(const [id,title]of [['activities','Activities'],['places','Places to visit'],['spells','My magic']]){const b=document.createElement('button');b.textContent=title;b.setAttribute('aria-pressed',String(tab===id));b.onclick=()=>heritageBoard(id);$('heritageTabs').append(b)}function card(title,text,label,fn){const a=document.createElement('article');a.className='life-board-card';a.innerHTML='<h3>'+lifeEsc(title)+'</h3><p>'+lifeEsc(text)+'</p>';const b=document.createElement('button');b.textContent=label;b.onclick=fn;a.append(b);$('heritageContent').append(a)}if(tab==='activities')heritage.activities.forEach(a=>{const i=heritage.current(state,a.id);card((i.complete?'✓ ':'')+a.title,(i.complete?'First reward collected. Repeat for enjoyment.':a.reward+' mooncoins + '+a.prize)+' · Next: '+i.step.text,i.complete?'Practice again':'Begin or continue',()=>heritageActivity(a.id))});if(tab==='places')Object.entries(heritageRooms).forEach(([kind,r])=>card(r.title,r.description,'Visit '+r.title,()=>heritageTravel(r.district,kind,()=>heritageRoom(kind))));if(tab==='spells'){for(const [id,name,text]of [['mending','Mending Light','A ribbon of silver stitches and a reminder that careful repairs preserve good work.'],['waylight','Waylight','Little stars reveal the next lead in your family’s journey.'],['bloom','Bloomcall','A drifting bloom of moonflower lights carries your garden’s welcome.']])card(name,(h.spells[id]?'Learned. ':'Learn this at the Spell Atelier. ')+text,h.spells[id]?'Cast '+name:'Learn '+name,()=>h.spells[id]?heritageCast(id):heritageActivity(id));action(h.magicOn?'Quiet the magical lights':'Restore the magical lights',()=>{h.magicOn=!h.magicOn;lifeCommit();heritageBoard('spells')})}action('Visit the original shoemaker’s shop',heritageOriginal);action('Return to the city',()=>{$('modal').close();cityDraw()})}
let heritageCastTimer=null;
function heritageCast(id){if(!heritage.ensure(state).spells[id])return;$('modal').close();const host=$('heritageMagic');host.dataset.cast=id;clearTimeout(heritageCastTimer);heritageCastTimer=setTimeout(()=>{delete host.dataset.cast},16000);const names={mending:'Silver light stitches across the air above your hands.',waylight:'The stars point toward your next family-story lead.',bloom:'Moonflower lights bloom around you.'};cityMessage(names[id]);if(id==='waylight'){modal('The Waylight answers','<p>'+lifeEsc(cityStory.current(state)?.title||'The family is reunited. There are still neighbors to help and stories to share.')+'</p>');action('Follow the guiding stars',lifeContinue);action('Stay here',()=>{$('modal').close();cityDraw()})}}
function heritageMagic(){let host=$('heritageMagic');if(!host){host=document.createElement('div');host.id='heritageMagic';host.setAttribute('aria-hidden','true');$('cityScene').append(host);for(let i=0;i<24;i++){const p=document.createElement('i');p.style.cssText='--x:'+(5+(i*29)%90)+'%;--y:'+(12+(i*17)%68)+'%;--d:'+(5+i%7)+'s;--delay:-'+(i*.43)+'s;';host.append(p)}}const h=heritage.ensure(state);host.hidden=!h.magicOn;host.classList.toggle('heritage-presence',cityInside==='originalShop'||cityInside==='spellAtelier'||cityInside==='memoryHall')}
const heritageHotspotsBefore=cityBuildHotspots;cityBuildHotspots=function(){heritageHotspotsBefore();if(cityInside==='originalShop'){$('cityHotspots').querySelector('.work')?.remove();const points=[[43,57],[86,50],[22,68],[56,49],[75,26],[10,34]];heritage.exhibits.forEach((e,i)=>cityTarget(e[1],...points[i],()=>heritageExamine(e[0]),'heritage-object'))}};
const heritageActionsBefore=cityBuildActions;cityBuildActions=function(){heritageActionsBefore();if(cityInside==='originalShop'){const c=cityCard('The original fairy tale','Play through the last piece of leather, the midnight helpers, and the couple’s thank-you gifts.','Play the original tale',()=>heritageActivity('originaltale'),'✦');$('comfortPlaces').prepend(c);cityCard('A furnished memorial','The bench, tools, hearth, curtain and little outfits remain in place.','Examine the preserved objects',heritageExhibits,'◇');}for(const a of heritage.activities){const i=heritage.current(state,a.id);if(heritage.at(i.step,lifeWhere())&&a.id!=='originaltale')cityCard(a.title,i.step.text,i.complete?'Practice this activity':'Begin or continue activity',()=>heritageActivity(a.id),'✦')}if(!cityInside&&scene==='workshop'){const c=cityCard('The actual shop from the original tale','Visit the shoemaker and his wife’s preserved cottage. It is separate from the modern workshop.','Visit the original shop',heritageOriginal,'⌂');$('comfortPlaces').prepend(c)}};
const heritageDrawBefore=cityDraw;cityDraw=function(){heritageDrawBefore();heritageMagic();if(cityInside==='originalShop'){$('subtitle').textContent='The Elves and the Shoemaker · the original furnished cottage, preserved with gratitude.';$('hint').textContent='Examine the objects, remember the midnight helpers, or play through the original tale.'}else if(heritageRooms[cityInside])$('subtitle').textContent=heritageRooms[cityInside].description};comfortDraw=cityDraw;

function heritageMemory(index){const memories=[['The shoemaker','I prepared the last piece of leather for morning. When I woke, the shoes were already finished, with not a single stitch out of place.'],['His wife','The little helpers have done so much for us. Let us make them clothes, stockings and shoes to thank them.'],['The two little elves','When the gifts were waiting on the bench, the helpers dressed, danced with delight, and went freely on their way.']];const [name,text]=memories[index]||memories[0];modal(name+' · a memory of the tale','<p class="life-dialogue">'+lifeEsc(text)+'</p>');action('Play this remembered story',()=>heritageActivity('originaltale'));action('Return to the preserved room',()=>{$('modal').close();cityDraw()})}
const heritageTalkBefore=cityTalk;cityTalk=function(index){if(cityInside==='originalShop'){heritageMemory(index);return}heritageTalkBefore(index)};
const heritagePeopleBefore=cityBuildPeople;cityBuildPeople=function(){heritagePeopleBefore();if(cityInside!=='originalShop')return;$('cityPeople').replaceChildren();['The shoemaker','His wife','The two little elves'].forEach((name,index)=>{const b=document.createElement('button');b.className='city-person';b.textContent=name+' · a remembered voice';b.onclick=()=>heritageMemory(index);$('cityPeople').append(b)})};

window.ELDORIA_HERITAGE={version:1,visitOriginal:heritageOriginal,openBoard:heritageBoard};cityDraw();persist();
